#[no_mangle]
pub extern "C" fn linked_deque(v:*const i64,n:usize)->i64{if v.is_null()||n<2||n>20||n%2!=0{return -1;}let a=unsafe{std::slice::from_raw_parts(v,n)};let mut q=[0i64;40];let(mut h,mut t)=(16usize,16usize);let(mut out,mut place)=(0i64,1i64);for p in (0..n).step_by(2){let op=a[p];let val=a[p+1];if !(0..=6).contains(&op){return -1;}if op<2{if !(-15..=15).contains(&val){return -1;}if op==0{h-=1;q[h]=val;}else{q[t]=val;t+=1;}continue;}if val!=0{return -1;}let d=match op{2=>if h<t{let x=q[h]+16;h+=1;x}else{0},3=>if h<t{t-=1;q[t]+16}else{0},4=>if h<t{q[h]+16}else{0},5=>if h<t{q[t-1]+16}else{0},_=>if h==t{1}else{2}};out+=d*place;place*=32;}out}
